const raw = (typeof msg.payload === 'string'
    ? msg.payload
    : String(msg.payload)
).trim();

msg.rawMessage = raw;

function parseCell(token) {
    const m = token.match(/^(\d+)\.(\d+)\.([0-9a-fA-F]+)\.([0-9a-fA-F]+)@(-?\d+)$/);
    if (!m) return null;
    return {
        mobileCountryCode: parseInt(m[1], 10),
        mobileNetworkCode: parseInt(m[2], 10),
        locationAreaCode:  parseInt(m[3], 16),
        cellId:            parseInt(m[4], 16),
        signalStrength:    parseInt(m[5], 10)
    };
}

const sosMatch = raw.match(/^SOS\s+IMEI:(\d+);?$/i);
if (sosMatch) {
    msg.imei = sosMatch[1];
    msg.isSOS = true;
    msg.topic = 'sos';
    msg.serving = null;
    msg.neighbors = [];
    node.status({ fill:'red', shape:'dot', text:'SOS from ' + msg.imei });
    return [null, msg];
}

const imeiMatch    = raw.match(/IMEI:(\d+)/);
const serviceMatch = raw.match(/service:\[([^\]]+)\]/);
const neighborRe   = /\[([^\]]+)\]/g;

if (!imeiMatch || !serviceMatch) {
    node.error('Unparseable message: ' + raw, msg);
    return [null, null];
}

const serving = parseCell(serviceMatch[1]);
if (!serving) {
    node.error('Unparseable serving cell: ' + serviceMatch[1], msg);
    return [null, null];
}

const neighbors = [];
let nm;
let skipFirst = true;
while ((nm = neighborRe.exec(raw)) !== null) {
    if (skipFirst) { skipFirst = false; continue; }
    const c = parseCell(nm[1]);
    if (c) neighbors.push(c);
}

msg.imei      = imeiMatch[1];
msg.isSOS     = false;
msg.topic     = 'location';
msg.serving   = serving;
msg.neighbors = neighbors;

msg.geoBody = {
    radioType: 'gsm',
    considerIp: true,
    cellTowers: [serving, ...neighbors]
};

node.status({ fill:'green', shape:'dot', text: msg.imei + ' · ' + (1+neighbors.length) + ' towers' });
return [msg, null];

// Prepare Geo request (montre Kii07) - version IoTLAB1 robuste
const apiKey = String(env.get('GOOGLE_GEO_API_KEY') || '').trim();
if (!apiKey || apiKey.startsWith('__')) {       // vide, ou masquee ("__PWRD__") si variable de type credential
    node.error('Cle API absente ou illisible : ' + (apiKey || '(vide)') + ' -> voir section 6.3', msg);
    node.status({ fill: 'red', shape: 'ring', text: 'cle API absente' });
    return null;
}
if (!/^AIza[0-9A-Za-z_-]{35}$/.test(apiKey)) node.warn('Format de cle inattendu (attendu : AIza + 35 caracteres)');
const s = msg.serving;
// Cell ID > 65535 => ce n'est pas un CID 2G (16 bits) : cellule LTE (ECI 28 bits)
const radio = (s.cellId > 65535) ? 'lte' : 'gsm';
msg.url     = 'https://www.googleapis.com/geolocation/v1/geolocate?key=' + apiKey;
msg.method  = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    radioType: radio,
    homeMobileCountryCode: s.mobileCountryCode,
    homeMobileNetworkCode: s.mobileNetworkCode,
    considerIp: false,                      // pas de repli trompeur sur l'IP du PC
    cellTowers: [s, ...msg.neighbors]
};
node.status({ fill: 'blue', shape: 'dot', text: radio + ' - ' + msg.payload.cellTowers.length + ' cellule(s)' });
return msg;

if (!msg.payload || msg.payload.error) {
    const e = (msg.payload && msg.payload.error) || {};
    const reason = (e.errors && e.errors[0] && e.errors[0].reason) || '';
    node.warn('Geolocation API : HTTP ' + msg.statusCode + ' ' + reason + ' - ' + (e.message || 'reponse vide') + ' (voir tableau des erreurs, section 6.3)');
    msg.lat      = null;
    msg.lng      = null;
    msg.accuracy = null;
} else {
    msg.lat      = msg.payload.location.lat;
    msg.lng      = msg.payload.location.lng;
    msg.accuracy = msg.payload.accuracy;
}

const watches = flow.get('watches') || {};
if (!watches[msg.imei]) {
    watches[msg.imei] = {
        imei:      msg.imei,
        lat:       msg.lat,
        lng:       msg.lng,
        accuracy:  msg.accuracy,
        sos:       msg.isSOS || false,
        serving:   msg.serving,
        neighbors: msg.neighbors,
        updatedAt: new Date().toISOString()
    };
} else {
    watches[msg.imei].lat       = msg.lat;
    watches[msg.imei].lng       = msg.lng;
    watches[msg.imei].accuracy  = msg.accuracy;
    watches[msg.imei].sos       = msg.isSOS || false;
    watches[msg.imei].updatedAt = new Date().toISOString();
}
flow.set('watches', watches);

msg.topic   = msg.isSOS ? 'sos' : 'location';
msg.payload = watches[msg.imei];

node.status({
    fill:  msg.lat ? 'green' : 'yellow',
    shape: 'dot',
    text:  msg.imei + ' → ' + (msg.lat ? msg.lat.toFixed(4)+','+msg.lng.toFixed(4) : 'no fix')
});

return msg;

const watches = flow.get('watches') || {};
if (!watches[msg.imei]) {
    watches[msg.imei] = {
        imei: msg.imei,
        lat: null, lng: null, accuracy: null,
        sos: true,
        serving: null,
        neighbors: [],
        updatedAt: new Date().toISOString()
    };
} else {
    watches[msg.imei].sos = true;
    watches[msg.imei].updatedAt = new Date().toISOString();
}
flow.set('watches', watches);

msg.payload = watches[msg.imei];
msg.topic   = 'sos';
msg.isSOS   = true;

const locStr = watches[msg.imei].lat
    ? watches[msg.imei].lat.toFixed(4) + ',' + watches[msg.imei].lng.toFixed(4)
    : 'unknown location';

msg.sosText = '⚠ SOS — IMEI ' + msg.imei + ' at ' + locStr + ' (' + new Date().toLocaleTimeString() + ')';

return msg;

const w = msg.payload;
if (!w.lat) return null;

msg.payload = {
    name:      w.imei,
    lat:       w.lat,
    lon:       w.lng,
    icon:      w.sos ? 'danger' : 'circle',
    iconColor: w.sos ? 'red' : 'blue',
    label:     w.imei.slice(-4),
    popup:     '<b>' + (w.sos ? '⚠ SOS — ' : '') + w.imei + '</b><br>' +
               'Lat: ' + w.lat.toFixed(5) + '<br>' +
               'Lng: ' + w.lng.toFixed(5) + '<br>' +
               '±' + Math.round(w.accuracy || 0) + ' m<br>' +
               'Updated: ' + w.updatedAt
};
return msg;

const watches = flow.get('watches') || {};
const rows = Object.values(watches).map(w => ({
    imei:      w.imei,
    sos:       w.sos,
    lat:       w.lat  != null ? w.lat.toFixed(5)  : '—',
    lng:       w.lng  != null ? w.lng.toFixed(5)  : '—',
    accuracy:  w.accuracy != null ? Math.round(w.accuracy) + ' m' : '—',
    updatedAt: w.updatedAt
}));
msg.payload = rows;
return msg;

// =====================================================================
//  IoTLAB1 - Tab5 : detection de mouvement + URL Google Static Maps
//  Entree : msg.payload = fiche montre {imei, lat, lng, accuracy, sos, updatedAt}
//           msg.isSOS (SOS recu)   msg.isAck (acquittement depuis la Tab5)
//  Sortie 1 -> watches/tab5 (retain)   Sortie 2 -> watches/cmd ("url#")
// =====================================================================
const w = msg.payload || {};
if (!w.imei) return [null, null];

const KEY       = env.get('GOOGLE_MAPS_STATIC_KEY') || env.get('GOOGLE_GEO_API_KEY') || 'VOTRE_CLE_STATIC_MAPS';
const MOVE_MIN  = Number(env.get('MOVE_MIN_M') || 150);   // seuil mini (m)
const MAP_W = 640, MAP_H = 280, MAP_SCALE = 2;            // => 1280 x 560 px sur la Tab5

const ref   = flow.get('tab5Ref')   || {};   // position de reference par IMEI
const latch = flow.get('sosLatch')  || {};   // SOS memorise jusqu'a acquittement

function haversine(lat1, lon1, lat2, lon2) {
    const R = 6371000, toRad = d => d * Math.PI / 180;
    const dLat = toRad(lat2 - lat1), dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLon/2)**2;
    return 2 * R * Math.asin(Math.sqrt(a));
}
function circlePath(lat, lng, r, n) {          // cercle d'incertitude (n points)
    const pts = [];
    for (let i = 0; i <= n; i++) {
        const t = 2 * Math.PI * i / n;
        const dLat = (r * Math.cos(t)) / 111320;
        const dLng = (r * Math.sin(t)) / (111320 * Math.cos(lat * Math.PI / 180));
        pts.push((lat + dLat).toFixed(5) + ',' + (lng + dLng).toFixed(5));
    }
    return pts.join('|');
}
function zoomFor(acc) {
    if (!acc)        return 15;
    if (acc < 250)   return 16;
    if (acc < 800)   return 15;
    if (acc < 2000)  return 14;
    if (acc < 5000)  return 13;
    return 12;
}

// ---- 1. Gestion du verrou SOS -------------------------------------
if (msg.isSOS) latch[w.imei] = { since: new Date().toISOString() };
if (msg.isAck) delete latch[w.imei];
flow.set('sosLatch', latch);
const sosActive = !!latch[w.imei];

// ---- 2. Detection de mouvement -----------------------------------
const hasFix = (w.lat !== null && w.lat !== undefined);
const prev   = ref[w.imei];
let dist = null, moved = false, seuil = null;
if (hasFix && prev && !msg.isSOS && !msg.isAck) {
    dist  = haversine(prev.lat, prev.lng, w.lat, w.lng);
    seuil = Math.max(MOVE_MIN, ((w.accuracy || 0) + (prev.acc || 0)) / 2);
    moved = dist > seuil;
}
// La reference n'est mise a jour qu'au 1er fix ou apres un vrai mouvement
if (hasFix && (!prev || moved)) {
    ref[w.imei] = { lat: w.lat, lng: w.lng, acc: w.accuracy || 0, ts: w.updatedAt };
}
flow.set('tab5Ref', ref);

// ---- 3. Qualification de l'evenement ------------------------------
let event;
if (msg.isAck)            event = 'SOS_ACK';
else if (msg.isSOS)       event = hasFix ? 'SOS' : 'SOS_NOFIX';
else if (!hasFix)         event = 'NOFIX';
else if (sosActive)       event = 'SOS_UPDATE';
else if (!prev)           event = 'FIRST_FIX';
else if (moved)           event = 'MOVE';
else                      event = 'POSITION';

const hhmm = new Date().toLocaleTimeString('fr-FR', { timeZone: 'Europe/Paris' });
const texts = {
    SOS:        'SOS ! Derniere position connue',
    SOS_NOFIX:  'SOS ! Position inconnue - localisation demandee',
    SOS_UPDATE: 'SOS en cours - position actualisee',
    SOS_ACK:    'SOS acquitte',
    NOFIX:      'Pas de fix (Geolocation API)',
    FIRST_FIX:  'Premiere position recue',
    MOVE:       'Mouvement detecte : ' + Math.round(dist || 0) + ' m',
    POSITION:   'Position stable (' + Math.round(dist || 0) + ' m)'
};

// ---- 4. URL Google Static Maps (format jpg-baseline pour TJpgDec) --
let mapUrl = '';
if (hasFix) {
    const acc = Math.round(w.accuracy || 0);
    const color = sosActive ? 'red' : 'blue';
    const p = [];
    p.push('center=' + w.lat.toFixed(5) + ',' + w.lng.toFixed(5));
    p.push('zoom=' + zoomFor(acc));
    p.push('size=' + MAP_W + 'x' + MAP_H + '&scale=' + MAP_SCALE);
    p.push('maptype=roadmap&format=jpg-baseline&language=fr');
    if (acc > 0) p.push('path=' + encodeURIComponent('fillcolor:0x' + (sosActive ? 'FF0000' : '1E64FF') + '33|color:0x'
                       + (sosActive ? 'FF0000' : '1E64FF') + 'AA|weight:2|' + circlePath(w.lat, w.lng, acc, 24)));
    if (moved && prev) p.push('markers=' + encodeURIComponent('size:mid|color:gray|label:P|' + prev.lat.toFixed(5) + ',' + prev.lng.toFixed(5)));
    p.push('markers=' + encodeURIComponent('color:' + color + '|label:' + (sosActive ? 'S' : 'K') + '|' + w.lat.toFixed(5) + ',' + w.lng.toFixed(5)));
    p.push('key=' + KEY);
    mapUrl = 'https://maps.googleapis.com/maps/api/staticmap?' + p.join('&');
}

const out1 = {
    topic: 'watches/tab5',
    payload: {
        imei: w.imei, event: event, sos: sosActive,
        lat: hasFix ? Number(w.lat.toFixed(6)) : null,
        lng: hasFix ? Number(w.lng.toFixed(6)) : null,
        acc: hasFix ? Math.round(w.accuracy || 0) : null,
        dist: dist !== null ? Math.round(dist) : null,
        seuil: seuil !== null ? Math.round(seuil) : null,
        ts: hhmm, msg: texts[event], mapUrl: mapUrl
    }
};
// Sur SOS : on redemande une position fraiche a la montre (via le smartphone)
const out2 = msg.isSOS ? { topic: 'watches/cmd', payload: 'url#' } : null;

node.status({ fill: sosActive ? 'red' : (moved ? 'yellow' : 'green'), shape: 'dot', text: event + ' ' + hhmm });
return [out1, out2];

// Acquittement SOS publie par la Tab5 sur watches/ack : {"imei":"..."}
let imei = null;
try { imei = (typeof msg.payload === 'object') ? msg.payload.imei : JSON.parse(msg.payload).imei; } catch (e) {}
const watches = flow.get('watches') || {};
const ids = imei ? [imei] : Object.keys(watches);
return [ids.filter(id => watches[id]).map(id => ({ payload: Object.assign({}, watches[id], { sos: false }), isAck: true }))];

// Test : geolocaliser une cellule relevee sur un smartphone (NetMonster, Field Test...)
// msg.payload = {"rat":"lte","mcc":208,"mnc":1,"tac":<TAC>,"ci":<Cell ID complet>,"rsrp":<dBm>}
//   rat = "lte" (4G : ci = ECI = eNB x 256 + CID)   ou   "nr" (5G SA : ci = NCI 36 bits)
const c = msg.payload || {};
const apiKey = String(env.get('GOOGLE_GEO_API_KEY') || '').trim();
if (!apiKey || apiKey.startsWith('__')) { node.error('Cle API absente ou illisible -> section 6.3', msg); return null; }
const rat = (c.rat || 'lte').toLowerCase();
const ci  = Number(c.ci !== undefined ? c.ci : c.eci);
const tower = { mobileCountryCode: Number(c.mcc), mobileNetworkCode: Number(c.mnc), signalStrength: Number(c.rsrp) };
if (c.tac !== undefined && c.tac !== '') tower.locationAreaCode = Number(c.tac);
if (rat === 'nr') tower.newRadioCellId = ci; else tower.cellId = ci;   // cellId est refuse en NR
msg.imei = 'SMARTPHONE';
msg.isSOS = false;
msg.serving = tower;
msg.neighbors = [];
msg.url = 'https://www.googleapis.com/geolocation/v1/geolocate?key=' + apiKey;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { radioType: rat, considerIp: false, cellTowers: [tower] };
node.status({ fill: 'blue', shape: 'dot', text: rat === 'nr' ? 'NR ' + ci : 'eNB ' + Math.floor(ci / 256) + ' / CID ' + (ci % 256) });
return msg;
